const cfg = $('Configure ICP Targets & Cooldown Policy').first()?.json || {};
const targetSignals = new Set(Array.isArray(cfg.targetSignals) ? cfg.targetSignals : []);
const cooldownDays = Number(cfg.cooldownDays ?? 45);
const minCompositeScore = Number(cfg.minCompositeScore ?? 60);
const requireFresh14d = cfg.requireFresh14dPosting !== false;
const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();
const cooldownMs = cooldownDays * 86400 * 1000;

const state = $getWorkflowStaticData('global');
if (!state.companyLedger) state.companyLedger = {};
const ledger = state.companyLedger;

function canonicalDomain(raw) {
  const cleaned = String(raw || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
  return cleaned || null;
}

const byCompany = {};
for (const item of $input.all()) {
  const row = item.json || {};
  const dom = canonicalDomain(row.domain);
  if (!dom) continue;
  if (!byCompany[dom]) {
    byCompany[dom] = {
      domain: dom,
      atsProviders: new Set(),
      careersUrls: new Set(),
      openRolesCount: 0,
      postedLast14Days: 0,
      hiringSignals: new Set(),
      techFromJobs: new Set(),
      salesOpportunities: new Set(),
      cms: null,
      hasLlmsTxt: null,
    };
  }
  const rec = byCompany[dom];

  // Ingest ATS Hiring-Intent record (merges cleanly even if same company appears on multiple ATS boards)
  if (Array.isArray(row.hiringIntentSignals) || row.atsProvider) {
    if (row.atsProvider) rec.atsProviders.add(String(row.atsProvider));
    if (row.careersUrl) rec.careersUrls.add(String(row.careersUrl));
    rec.openRolesCount = Math.max(rec.openRolesCount, Number(row.openRolesCount || 0));
    rec.postedLast14Days = Math.max(rec.postedLast14Days, Number(row.velocity?.postedLast14Days || 0));
    for (const s of row.hiringIntentSignals || []) rec.hiringSignals.add(String(s));
    for (const t of row.techStackFromJobs || []) rec.techFromJobs.add(String(t));
  }

  // Ingest Website Tech Stack & SEO/GEO record
  if (Array.isArray(row.salesOpportunities) || row.seo || row.geo) {
    if (row.cms) rec.cms = row.cms;
    if (typeof row.geo?.hasLlmsTxt === 'boolean') rec.hasLlmsTxt = row.geo.hasLlmsTxt;
    for (const op of row.salesOpportunities || []) rec.salesOpportunities.add(String(op));
  }
}

const eligibleDomains = [];
const companySnapshots = {};
const suppressedLog = [];

for (const [dom, rec] of Object.entries(byCompany)) {
  const matchedHiring = [...rec.hiringSignals].filter((s) => targetSignals.size === 0 || targetSignals.has(s));
  const opps = [...rec.salesOpportunities];

  // Composite buying-intent score (0-100): Hiring intent + 14d freshness + tech/GEO gaps
  let score = 0;
  if (matchedHiring.length > 0) score += 45;
  if (rec.postedLast14Days >= 3) score += 25;
  else if (rec.postedLast14Days >= 1) score += 15;
  if (opps.length >= 2) score += 20;
  else if (opps.length === 1) score += 10;
  if (rec.techFromJobs.size >= 2) score += 10;
  score = Math.min(100, score);

  const prior = ledger[dom] || {
    domain: dom,
    first_seen_at: nowIso,
    last_seen_at: nowIso,
    last_contacted_at: null,
    signals: {},
  };
  prior.last_seen_at = nowIso;

  const primarySignalUrl = [...rec.careersUrls][0] || `https://${dom}`;
  for (const sig of [...matchedHiring, ...opps]) {
    if (!prior.signals[sig]) {
      prior.signals[sig] = { first_seen_at: nowIso, last_seen_at: nowIso, source_url: primarySignalUrl };
    } else {
      prior.signals[sig].last_seen_at = nowIso;
      prior.signals[sig].source_url = primarySignalUrl;
    }
  }
  ledger[dom] = prior;

  const lastContactMs = prior.last_contacted_at ? Date.parse(prior.last_contacted_at) : 0;
  const withinCooldown = lastContactMs > 0 && (nowMs - lastContactMs) < cooldownMs;
  const lacksFreshPosting = requireFresh14d && matchedHiring.length > 0 && rec.postedLast14Days === 0 && opps.length === 0;

  if (withinCooldown) {
    suppressedLog.push({ domain: dom, reason: 'COOLDOWN_ACTIVE', last_contacted_at: prior.last_contacted_at });
    continue;
  }
  if (lacksFreshPosting) {
    suppressedLog.push({ domain: dom, reason: 'STALE_HIRING_SIGNALS_0_IN_14D' });
    continue;
  }
  if (matchedHiring.length === 0 && opps.length === 0) {
    suppressedLog.push({ domain: dom, reason: 'NO_MATCHING_INTENT_SIGNALS' });
    continue;
  }

  eligibleDomains.push(dom);
  companySnapshots[dom] = {
    domain: dom,
    compositeIntentScore: score,
    meetsQualifiedThreshold: score >= minCompositeScore,
    atsProviders: [...rec.atsProviders].join(', ') || null,
    signalSourceUrl: primarySignalUrl,
    openRolesCount: rec.openRolesCount,
    postedLast14Days: rec.postedLast14Days,
    matchedHiringSignals: matchedHiring,
    salesOpportunities: opps,
    internalTechFromJobs: [...rec.techFromJobs].slice(0, 10),
    first_seen_at: prior.first_seen_at,
    last_seen_at: prior.last_seen_at,
  };
}

return [{
  json: {
    hasEligibleAccounts: eligibleDomains.length > 0,
    eligibleCount: eligibleDomains.length,
    suppressedCount: suppressedLog.length,
    suppressedLog,
    domains: eligibleDomains,
    companySnapshots,
    minCompositeScore
  }
}];

const gate = $('Canonical Dedup, Signal Freshness & Cooldown Gate').first()?.json || {};
const snapshots = gate.companySnapshots || {};
const state = $getWorkflowStaticData('global');
if (!state.companyLedger) state.companyLedger = {};
const nowIso = new Date().toISOString();
const out = [];

for (const item of $input.all()) {
  const lead = item.json || {};
  if (lead.status !== 'enriched' || !lead.domain) continue;
  const dom = String(lead.domain).toLowerCase().trim();
  const snap = snapshots[dom];
  if (!snap) continue;

  const verifiedDms = Array.isArray(lead.decisionMakers)
    ? lead.decisionMakers.filter((dm) => dm && dm.verifiedForBilling === true && dm.email)
    : [];

  // Separate a verified contact address from a true qualified sales lead
  const isQualifiedLead = Boolean(snap.meetsQualifiedThreshold && (verifiedDms.length > 0 || snap.postedLast14Days >= 1));
  const leadStage = isQualifiedLead ? 'qualified_hiring_lead' : 'verified_contact_watchlist';

  if (isQualifiedLead && state.companyLedger[dom]) {
    state.companyLedger[dom].last_contacted_at = nowIso;
  }

  const common = {
    domain: dom,
    companyName: lead.companyName || dom,
    leadStage,
    compositeIntentScore: snap.compositeIntentScore,
    atsProviders: snap.atsProviders,
    openRolesCount: snap.openRolesCount,
    postedLast14Days: snap.postedLast14Days,
    matchedHiringSignals: (snap.matchedHiringSignals || []).join(', '),
    salesOpportunities: (snap.salesOpportunities || []).join(', '),
    internalTechFromJobs: (snap.internalTechFromJobs || []).join(', '),
    first_seen_at: snap.first_seen_at,
    last_seen_at: snap.last_seen_at,
    signal_source_url: snap.signalSourceUrl,
  };

  if (verifiedDms.length > 0) {
    for (const dm of verifiedDms) {
      out.push({
        json: {
          ...common,
          contactType: 'verified_decision_maker',
          contactName: dm.fullName,
          contactRole: dm.role,
          contactEmail: dm.email,
          contact_source_url: dm.sourceUrl || lead.sourceUrl || null
        }
      });
    }
  } else if (lead.primaryEmail) {
    out.push({
      json: {
        ...common,
        contactType: 'company_primary_email',
        contactName: null,
        contactRole: null,
        contactEmail: lead.primaryEmail,
        contact_source_url: lead.sourceUrl || null
      }
    });
  }
}

return out;
